    def _te_source(self, name: str) -> str:
        # te_<base> -> base interaction / raw column name
        mapping = {
            "te_coupon_time": "ix_coupon_time",
            "te_coupon_exp": "ix_coupon_expiration",
            "te_coupon_time_exp": "ix_coupon_time_exp",
            "te_coupon_income": "ix_coupon_income",
            "te_occupation": "occupation",
        }
        return mapping[name]

    def _cnt_source(self, name: str) -> str:
        mapping = {
            "cnt_coupon_time": "ix_coupon_time",
            "cnt_coupon_exp": "ix_coupon_expiration",
            "cnt_occupation": "occupation",
        }
        return mapping[name]

    def _fit_te_maps(self, raw: pd.DataFrame, y: np.ndarray) -> None:
        y = np.asarray(y, dtype=np.float64)
        glob = float(np.mean(y)) if len(y) else 0.5
        # smoothing strength
        k = 20.0
        for c in self.te_cols:
            src = self._te_source(c)
            if src not in raw.columns:
                self.te_maps[c] = {}
                self.te_global[c] = glob
                continue
            keys = raw[src].map(_cat_key).tolist()
            sums: Dict[str, float] = {}
            cnts: Dict[str, int] = {}
            for kk, yy in zip(keys, y):
                sums[kk] = sums.get(kk, 0.0) + yy
                cnts[kk] = cnts.get(kk, 0) + 1
            mp: Dict[str, float] = {}
            for kk, s in sums.items():
                n_k = cnts[kk]
                mp[kk] = (s + k * glob) / (n_k + k)
            self.te_maps[c] = mp
            self.te_global[c] = glob

    def _fit_count_maps(self, raw: pd.DataFrame) -> None:
        for c in self.count_cols:
            src = self._cnt_source(c)
            if src not in raw.columns:
                self.count_maps[c] = {}
                continue
            keys = raw[src].map(_cat_key).tolist()
            counts: Dict[str, int] = {}
            for kk in keys:
                counts[kk] = counts.get(kk, 0) + 1
            self.count_maps[c] = {kk: float(v) for kk, v in counts.items()}

    def _src_to_fe(self, src: str) -> str:
        # for the "occupation" source, it maps to "cat_occupation"
        if src in CAT_COLS_RAW or src in self.interaction_names:
            return src
        return src

    def transform(self, df: pd.DataFrame) -> pd.DataFrame:
        raw = self._raw(df)
        out = pd.DataFrame(index=pd.RangeIndex(len(df)))
        for c in self.num_cols:
            name = c[len("num_"):]
            arr = pd.to_numeric(raw[name], errors="coerce").to_numpy(dtype=np.float64)
            arr = np.where(np.isfinite(arr), arr, self.num_medians.get(name, 0.0))
            out[c] = arr
        for c in self.cat_cols:
            name = c[len("cat_"):]
            vocab = self.vocab.get(name, {})
            out[c] = np.asarray(
                [float(vocab.get(_cat_key(v), -1)) for v in raw[name].tolist()],
                dtype=np.float64,
            )
        for c in self.te_cols:
            src = self._te_source(c)
            mp = self.te_maps.get(c, {})
            glob = self.te_global.get(c, 0.5)
            if src in raw.columns:
                out[c] = np.asarray(
                    [float(mp.get(_cat_key(v), glob)) for v in raw[src].tolist()],
                    dtype=np.float64,
                )
            else:
                out[c] = glob
        for c in self.count_cols:
            src = self._cnt_source(c)
            mp = self.count_maps.get(c, {})
            if src in raw.columns:
                out[c] = np.asarray(
                    [float(mp.get(_cat_key(v), 0.0)) for v in raw[src].tolist()],
                    dtype=np.float64,
                )
            else:
                out[c] = 0.0
        return out[self.feature_names]


def split_feature_columns(names: Sequence[str]):
    cat_cols = [n for n in names if n.startswith("cat_")]
    num_cols = [n for n in names if not n.startswith("cat_")]
    return cat_cols, num_cols


class Normalizer:
    def __init__(self):
        self.mean = None
        self.std = None

    def fit(self, X) -> "Normalizer":
        X = np.asarray(X, dtype=np.float64)
        if X.ndim != 2 or X.shape[1] == 0:
            self.mean = np.zeros(0)
            self.std = np.ones(0)
            return self
        mean = np.nanmean(X, axis=0)
        std = np.nanstd(X, axis=0)
        self.mean = np.where(np.isfinite(mean), mean, 0.0)
        self.std = np.where(np.isfinite(std) & (std > 1e-8), std, 1.0)
        return self

    def transform(self, X) -> np.ndarray:
        X = np.asarray(X, dtype=np.float64)
        if X.ndim != 2 or X.shape[1] == 0 or self.mean is None:
            return X.astype(np.float32)
        return ((X - self.mean) / self.std).astype(np.float32)

    def state_dict(self) -> Dict[str, Any]:
        return {"mean": self.mean, "std": self.std}

    def load_state_dict(self, state: Dict[str, Any]) -> None:
        self.mean = state["mean"]
        self.std = state["std"]


class CouponModel(nn.Module):
    def __init__(self, cards, n_num, n_classes=2, emb_dim=8, hidden=128, dropout=0.2):
        super().__init__()
        cards = [int(c) for c in cards]
        dims = [int(min(emb_dim, max(2, (c + 1) // 2))) for c in cards]
        self.embs = nn.ModuleList([nn.Embedding(c, d) for c, d in zip(cards, dims)])
        in_dim = int(sum(dims)) + int(n_num)
        h2 = max(16, hidden // 2)
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.BatchNorm1d(hidden),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden, h2),
            nn.BatchNorm1d(h2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(h2, n_classes),
        )

    def forward(self, xc, xn):
        parts = [emb(xc[:, i]) for i, emb in enumerate(self.embs)]
        if xn.shape[1] > 0:
            parts.append(xn)
        return self.net(torch.cat(parts, dim=1))


class TrainConfig:
    def __init__(self):
        self.epochs = 40
        self.batch_size = 256
        self.lr = 2e-3
        self.weight_decay = 1e-4
        self.emb_dim = 8
        self.hidden = 128
        self.dropout = 0.2
        self.n_seeds = 3
        self.patience = 8


def _shift_cat(cat, cards):
    cat = np.asarray(cat)
    cards = [int(c) for c in cards]
    if cat.size == 0:
        return np.zeros((cat.shape[0], 0), dtype=np.int64), cards
    shifted = np.nan_to_num(cat, nan=-1.0).astype(np.int64) + 1
    for j, c in enumerate(cards):
        if c > 0 and j < shifted.shape[1]:
            shifted[:, j] = np.clip(shifted[:, j], 0, c - 1)
    return shifted, cards


def _predict_proba_single(model, cat_shifted, num_mat, batch_size=512):
    device = get_device()
    model.to(device).eval()
    chunks = []
    n = len(cat_shifted)
    for start in range(0, n, batch_size):
        end = min(start + batch_size, n)
        xc = torch.from_numpy(cat_shifted[start:end]).long().to(device)
        xn = torch.from_numpy(num_mat[start:end].astype(np.float32)).to(device)
        with torch.no_grad():
            chunks.append(torch.softmax(model(xc, xn), dim=1).cpu().numpy())
    if not chunks:
        return np.zeros((n, 2), dtype=np.float64)
    return np.concatenate(chunks, axis=0).astype(np.float64)


def _ensemble_proba(models, cat_shifted, num, batch_size=512):
    if not models:
        return None
    probs = [_predict_proba_single(m, cat_shifted, num, batch_size) for m in models]
    return np.mean(probs, axis=0)


def load_train_data(data_dir):
    features = pd.read_csv(os.path.join(data_dir, "features.csv"))
    labels = pd.read_csv(os.path.join(data_dir, "labels.csv"))
    y = labels.iloc[:, 0].to_numpy()
    schema = {}
    sp = os.path.join(data_dir, "schema.json")
    if os.path.exists(sp):
        with open(sp, "r") as f:
            schema = json.load(f)
    return features, y, schema


def load_predict_data(data_dir):
    features = pd.read_csv(os.path.join(data_dir, "features.csv"))
    schema = {}
    sp = os.path.join(data_dir, "schema.json")
    if os.path.exists(sp):
        with open(sp, "r") as f:
            schema = json.load(f)
    return features, schema


def _prepare_fold(fe, df):
    Xfe = fe.transform(df).reindex(columns=fe.feature_names, fill_value=0.0)
    cat_cols, num_cols = split_feature_columns(fe.feature_names)
    cat = (
        np.nan_to_num(Xfe[cat_cols].values, nan=-1.0)
        if cat_cols
        else np.zeros((len(Xfe), 0))
    )
    num = (
        Xfe[num_cols].values.astype(np.float32)
        if num_cols
        else np.zeros((len(Xfe), 0), dtype=np.float32)
    )
    return cat, num, cat_cols, num_cols


def _prepare_gbdt_matrix(fe, df, feature_names=None):
    cols = list(feature_names) if feature_names is not None else list(fe.feature_names)
    Xfe = fe.transform(df).reindex(columns=cols, fill_value=0.0)
    X = Xfe.values.astype(np.float32)
    X = np.nan_to_num(X, nan=-1.0, posinf=0.0, neginf=0.0)
    return X


def _train_one_model(
    seed, Xc, Xn, y, cards, n_num, n_classes, cfg,
    Xc_val=None, Xn_val=None, y_val=None,
):
    torch.manual_seed(seed)
    np.random.seed(seed)
    model = CouponModel(cards, n_num, n_classes, cfg.emb_dim, cfg.hidden, cfg.dropout)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=max(1, cfg.epochs))
    lossf = nn.CrossEntropyLoss()
    Xt = torch.from_numpy(np.asarray(Xc, dtype=np.int64)).long()
    Nt = torch.from_numpy(np.asarray(Xn, dtype=np.float32))
    Yt = torch.from_numpy(np.asarray(y, dtype=np.int64)).long()
    n = len(Yt)
    idx = np.arange(n)

    has_val = (
        Xc_val is not None and Xn_val is not None and y_val is not None
        and len(np.asarray(y_val)) > 0
    )
    if has_val:
        Xv = torch.from_numpy(np.asarray(Xc_val, dtype=np.int64)).long()
        Nv = torch.from_numpy(np.asarray(Xn_val, dtype=np.float32))
        Yv = np.asarray(y_val, dtype=np.int64)

    best_state = copy.deepcopy(model.state_dict())
    best_acc, since = -1.0, 0
    for ep in range(cfg.epochs):
        model.train()
        np.random.shuffle(idx)
        for s in range(0, n, cfg.batch_size):
            b = idx[s:s + cfg.batch_size]
            if len(b) < 2:
                continue
            opt.zero_grad()
            loss = lossf(model(Xt[b], Nt[b]), Yt[b])
            loss.backward()
            opt.step()
        sched.step()
        if has_val:
            model.eval()
            with torch.no_grad():
                p = torch.softmax(model(Xv, Nv), dim=1).numpy()
            acc = float((p.argmax(1) == Yv).mean())
            if acc > best_acc:
                best_acc, since = acc, 0
                best_state = copy.deepcopy(model.state_dict())
            else:
                since += 1
                if since >= cfg.patience:
                    break
    if has_val:
        model.load_state_dict(best_state)
    model.eval()
    return model


GBDT_CONFIGS = [
    {
        "max_iter": 500, "learning_rate": 0.05, "max_leaf_nodes": 31,
        "min_samples_leaf": 20, "l2_regularization": 0.1, "max_bins": 255,
        "early_stopping": True, "validation_fraction": 0.1,
        "n_iter_no_change": 15, "random_state": 42,
    },
    {
        "max_iter": 300, "learning_rate": 0.03, "max_leaf_nodes": 63,
        "min_samples_leaf": 10, "l2_regularization": 0.5, "max_bins": 255,
        "early_stopping": True, "validation_fraction": 0.1,
        "n_iter_no_change": 15, "random_state": 43,
    },
]


def _train_gbdt(X_tr, y_tr):
    if not HAS_GBDT:
        return []
    models = []
    for gc in GBDT_CONFIGS:
        try:
            clf = HistGradientBoostingClassifier(**gc)
            clf.fit(X_tr, y_tr)
            models.append(clf)
        except Exception:
            try:
                clf = GradientBoostingClassifier(
                    n_estimators=300, max_depth=5, learning_rate=0.05,
                    random_state=int(gc.get("random_state", 42)),
                )
                clf.fit(X_tr, y_tr)
                models.append(clf)
            except Exception:
                pass
    return models


RF_CONFIGS = [
    {"n_estimators": 400, "max_depth": None, "min_samples_leaf": 2,
     "max_features": "sqrt", "random_state": 42, "n_jobs": 2},
    {"n_estimators": 400, "max_depth": 20, "min_samples_leaf": 4,
     "max_features": 0.5, "random_state": 43, "n_jobs": 2},
]


def _train_rf(X_tr, y_tr):
    if RandomForestClassifier is None:
        return []
    models = []
    for rc in RF_CONFIGS:
        try:
            clf = RandomForestClassifier(**rc)
            clf.fit(X_tr, y_tr)
            models.append(clf)
        except Exception:
            pass
    return models


def _predict_ens(models, X, n_classes):
    if not models:
        return None
    probas = []
    for m in models:
        p = np.asarray(m.predict_proba(X), dtype=np.float64)
        if p.shape[1] < n_classes:
            pad = np.zeros((p.shape[0], n_classes - p.shape[1]))
            p = np.concatenate([p, pad], axis=1)
        probas.append(p[:, :n_classes])
    return np.mean(probas, axis=0)


def _search_blend3(p_list, y_idx, n_steps=11):
    """Search simplex weights over up to 3 predictors maximizing accuracy."""
    k = len(p_list)
    if k == 0:
        return [1.0], 0.0
    if k == 1:
        return [1.0], float((p_list[0].argmax(1) == y_idx).mean())
    best_w = [1.0] + [0.0] * (k - 1)
    best_acc = float((p_list[0].argmax(1) == y_idx).mean())
    grids = np.linspace(0, 1, n_steps)
    if k == 2:
        for a in grids:
            w = [float(a), float(1 - a)]
            p = w[0] * p_list[0] + w[1] * p_list[1]
            acc = float((p.argmax(1) == y_idx).mean())
            if acc > best_acc:
                best_acc, best_w = acc, w
    elif k == 3:
        for a in grids:
            for b in grids:
                c = 1 - a - b
                if c < 0:
                    continue
                w = [float(a), float(b), float(c)]
                p = w[0] * p_list[0] + w[1] * p_list[1] + w[2] * p_list[2]
                acc = float((p.argmax(1) == y_idx).mean())
                if acc > best_acc:
                    best_acc, best_w = acc, w
    return best_w, best_acc


def run_train(data_dir, model_dir):
    torch.manual_seed(42)
    np.random.seed(42)
    features, y_raw, _schema = load_train_data(data_dir)
    label_map = sorted(pd.unique(y_raw).tolist(), key=lambda v: str(v))
    cls_to_idx = {c: i for i, c in enumerate(label_map)}
    y = np.asarray([cls_to_idx[v] for v in y_raw], dtype=np.int64)
    n_classes = len(label_map)
    print(f"[train] rows={len(features)} classes={label_map}")

    n = len(y)
    n_folds = 5
    rng = np.random.RandomState(7)
    folds = np.zeros(n, dtype=np.int64)
    for cls in np.unique(y):
        idx_c = np.where(y == cls)[0]
        rng.shuffle(idx_c)
        for kk, i in enumerate(idx_c):
            folds[i] = kk % n_folds

    # OOF accumulators
    oof_nn = np.zeros((n, n_classes), dtype=np.float64)
    oof_gb = np.zeros((n, n_classes), dtype=np.float64)
    oof_rf = np.zeros((n, n_classes), dtype=np.float64)

    cfg = TrainConfig()

    # CV: for each fold, fit fe (with TE) on TRAIN part of fold only
    for k in range(n_folds):
        val_mask = folds == k
        tr_mask = ~val_mask
        tr_df = features.iloc[np.where(tr_mask)[0]].reset_index(drop=True)
        val_df = features.iloc[np.where(val_mask)[0]].reset_index(drop=True)
        y_tr = y[tr_mask]
        y_va = y[val_mask]

        fe_fold = CouponFeatureEngineer().fit(tr_df, y_tr)
        cat_tr, num_tr, cat_cols, num_cols = _prepare_fold(fe_fold, tr_df)
        cat_va, num_va, _, _ = _prepare_fold(fe_fold, val_df)
        normalizer = Normalizer().fit(num_tr)
        num_tr_n = normalizer.transform(num_tr)
        num_va_n = normalizer.transform(num_va)
        cards = [len(fe_fold.vocab[c]) + 1 for c in
                 (list(CAT_COLS_RAW) + fe_fold.interaction_names)]
        cat_tr_s, cards = _shift_cat(cat_tr, cards)
        cat_va_s, _ = _shift_cat(cat_va, cards)

        # NN: train 2 seeds, average
        seed_probs = []
        for s in range(2):
            m = _train_one_model(
                100 + s, cat_tr_s, num_tr_n, y_tr, cards,
                num_tr_n.shape[1], n_classes, cfg,
                Xc_val=cat_va_s, Xn_val=num_va_n, y_val=y_va,
            )
            seed_probs.append(_predict_proba_single(m, cat_va_s, num_va_n))
        oof_nn[val_mask] = np.mean(seed_probs, axis=0)

        X_gb_tr = _prepare_gbdt_matrix(fe_fold, tr_df)
        X_gb_va = _prepare_gbdt_matrix(fe_fold, val_df)
        gb_models = _train_gbdt(X_gb_tr, y_tr)
        pg = _predict_ens(gb_models, X_gb_va, n_classes)
        if pg is not None:
            oof_gb[val_mask] = pg

        rf_models = _train_rf(X_gb_tr, y_tr)
        pr = _predict_ens(rf_models, X_gb_va, n_classes)
        if pr is not None:
            oof_rf[val_mask] = pr
        print(f"[train] fold {k + 1}/{n_folds} done")

    acc_nn = float((oof_nn.argmax(1) == y).mean())
    acc_gb = float((oof_gb.argmax(1) == y).mean()) if np.any(oof_gb) else 0.0
    acc_rf = float((oof_rf.argmax(1) == y).mean()) if np.any(oof_rf) else 0.0
    print(f"[train] OOF nn={acc_nn:.4f} gb={acc_gb:.4f} rf={acc_rf:.4f}")

    p_list = [oof_nn]
    names = ["nn"]
    if np.any(oof_gb):
        p_list.append(oof_gb); names.append("gb")
    if np.any(oof_rf):
        p_list.append(oof_rf); names.append("rf")
    blend_w, blend_acc = _search_blend3(p_list, y, n_steps=11)
    print(f"[train] blend weights {list(zip(names, blend_w))} acc={blend_acc:.4f}")

    # Refit final feature engineer on FULL train
    fe_full = CouponFeatureEngineer().fit(features, y)
    cat_full, num_full, cat_cols, num_cols = _prepare_fold(fe_full, features)
    normalizer_full = Normalizer().fit(num_full)
    num_full_n = normalizer_full.transform(num_full)
    cards_full = [len(fe_full.vocab[c]) + 1 for c in
                  (list(CAT_COLS_RAW) + fe_full.interaction_names)]
    cat_full_s, cards_full = _shift_cat(cat_full, cards_full)

    full_models = []
    for s in range(cfg.n_seeds):
        m = _train_one_model(
            200 + s, cat_full_s, num_full_n, y, cards_full,
            num_full_n.shape[1], n_classes, cfg,
        )
        full_models.append(m)

    X_gb_full = _prepare_gbdt_matrix(fe_full, features)
    gbdt_models = _train_gbdt(X_gb_full, y) if HAS_GBDT else []
    rf_models = _train_rf(X_gb_full, y)

    path = _save_bundle(
        model_dir, fe_full, normalizer_full, cat_cols, num_cols,
        cards_full, label_map, cfg, full_models, cfg.epochs,
        gbdt_models=gbdt_models, rf_models=rf_models,
        blend_names=names, blend_weights=blend_w,
        interaction_names=fe_full.interaction_names,
    )
    print(f"[train] saved -> {path}")


def _save_bundle(
    model_dir, fe, normalizer, cat_cols, num_cols, cards, label_map, cfg,
    models, epochs, gbdt_models=None, rf_models=None,
    blend_names=None, blend_weights=None, interaction_names=None,
):
    os.makedirs(model_dir, exist_ok=True)
    path = os.path.join(model_dir, BUNDLE_NAME)
    bundle = {
        "fe": fe,
        "feature_names": list(fe.feature_names),
        "normalizer_state": normalizer.state_dict(),
        "cat_cols": list(cat_cols),
        "num_cols": list(num_cols),
        "cards": list(cards),
        "label_map": list(label_map),
        "cfg": dict(cfg.__dict__),
        "state_dicts": [m.state_dict() for m in models],
        "epochs": int(epochs),
        "gbdt_models": list(gbdt_models) if gbdt_models else [],
        "rf_models": list(rf_models) if rf_models else [],
        "blend_names": list(blend_names) if blend_names else ["nn"],
        "blend_weights": list(blend_weights) if blend_weights else [1.0],
        "nn_cfg": {
            "emb_dim": int(getattr(cfg, "emb_dim", 8)),
            "hidden": int(getattr(cfg, "hidden", 128)),
            "dropout": float(getattr(cfg, "dropout", 0.2)),
        },
        "interaction_names": list(interaction_names) if interaction_names else [],
    }
    torch.save(bundle, path)
    return path


def _load_bundle(model_dir):
    path = os.path.join(model_dir, BUNDLE_NAME)
    try:
        return torch.load(path, map_location="cpu", weights_only=False)
    except TypeError:
        return torch.load(path, map_location="cpu")


def run_predict(data_dir, model_dir, output_path):
    bundle = _load_bundle(model_dir)
    fe = bundle["fe"]
    normalizer = Normalizer()
    normalizer.load_state_dict(bundle["normalizer_state"])
    cards = [int(c) for c in bundle["cards"]]
    label_map = bundle["label_map"]
    n_classes = len(label_map)
    num_cols = bundle["num_cols"]
    nn_cfg = bundle.get("nn_cfg") or {}
    interaction_names = bundle.get("interaction_names", []) or []

    models = []
    for sd in bundle.get("state_dicts", []):
        m = CouponModel(
            cards, len(num_cols), n_classes,
            int(nn_cfg.get("emb_dim", 8)),
            int(nn_cfg.get("hidden", 128)),
            float(nn_cfg.get("dropout", 0.2)),
        )
        m.load_state_dict(sd)
        m.eval()
        models.append(m)

    features, _schema = load_predict_data(data_dir)
    cat, num, _c, _n = _prepare_fold(fe, features)
    num_n = normalizer.transform(num)
    cat_shifted, cards = _shift_cat(cat, cards)

    p_nn = _ensemble_proba(models, cat_shifted, num_n)
    if p_nn is None:
        p_nn = np.zeros((len(features), n_classes))
        p_nn[:, 0] = 1.0

    X_gb = _prepare_gbdt_matrix(fe, features, bundle["feature_names"])
    p_gb = _predict_ens(bundle.get("gbdt_models", []) or [], X_gb, n_classes)
    p_rf = _predict_ens(bundle.get("rf_models", []) or [], X_gb, n_classes)

    probs_by_name = {"nn": p_nn}
    if p_gb is not None and p_gb.shape == p_nn.shape:
        probs_by_name["gb"] = p_gb
    if p_rf is not None and p_rf.shape == p_nn.shape:
        probs_by_name["rf"] = p_rf

    names = bundle.get("blend_names", ["nn"])
    weights = bundle.get("blend_weights", [1.0])
    total = 0.0
    proba = np.zeros_like(p_nn)
    for nm, w in zip(names, weights):
        if nm in probs_by_name:
            proba += float(w) * probs_by_name[nm]
            total += float(w)
    if total <= 1e-9:
        proba = p_nn
    else:
        proba = proba / total

    idx_pred = np.argmax(proba, axis=1)
    preds = [label_map[int(i)] for i in idx_pred]

    out = pd.DataFrame({
        "row_id": np.arange(len(features), dtype=np.int64),
        "prediction": preds,
    })
    out_dir = os.path.dirname(output_path)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    out.to_csv(output_path, index=False)
    print(f"[predict] wrote {len(out)} rows -> {output_path}")


def main():
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    p_train = sub.add_parser("train")
    p_train.add_argument("--data", required=True)
    p_train.add_argument("--model", required=True)
    p_pred = sub.add_parser("predict")
    p_pred.add_argument("--data", required=True)
    p_pred.add_argument("--model", required=True)
    p_pred.add_argument("--output", required=True)
    args = ap.parse_args()
    if args.cmd == "train":
        run_train(args.data, args.model)
    else:
        run_predict(args.data, args.model, args.output)


if __name__ == "__main__":
    main()
```

The key improvements:
1. **Interaction features** (`ix_coupon_time`, `ix_coupon_expiration`, etc.) as categorical embeddings — captures compositional coupon-context signal.
2. **OOF-safe target encoding** for interactions (`te_coupon_time`, etc.) via per-fold refit — no leakage.
3. **Count encoding** for frequent interactions.
4. **Third learner: RandomForest** ensemble, blended with NN+HGB via simplex weight search on OOF accuracy.
5. **Fixed duplicate function definitions** and cleaned up redundant code.
